{
  "root": "main_stack",
  "state": {
    "weatherData": [
      {
        "metric": "Temperature",
        "value": "15°C (59°F)"
      },
      {
        "metric": "Feels Like",
        "value": "14°C (57°F)"
      },
      {
        "metric": "Humidity",
        "value": "75%"
      },
      {
        "metric": "Wind",
        "value": "10 km/h (6 mph) NE"
      },
      {
        "metric": "Precipitation",
        "value": "10% chance"
      }
    ],
    "packingItems": [
      {
        "item": "Light Jacket",
        "reason": "Cool evenings"
      },
      {
        "item": "Umbrella",
        "reason": "Chance of rain"
      },
      {
        "item": "Comfortable Shoes",
        "reason": "Walking tours"
      },
      {
        "item": "Power Adapter",
        "reason": "UK Type G"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg",
        "padding": 16
      },
      "children": [
        "weather_card",
        "packing_essentials_section",
        "quick_actions_section",
        "sources_section"
      ]
    },
    "weather_card": {
      "type": "Card",
      "props": {},
      "children": [
        "weather_card_content_stack"
      ]
    },
    "weather_card_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "weather_title_icon_stack",
        "weather_description",
        "weather_details_table"
      ]
    },
    "weather_title_icon_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "weather_icon",
        "weather_location_text"
      ]
    },
    "weather_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/cloud.svg"
      },
      "children": []
    },
    "weather_location_text": {
      "type": "Text",
      "props": {
        "text": "London: Partly Cloudy",
        "variant": "h2"
      },
      "children": []
    },
    "weather_description": {
      "type": "Text",
      "props": {
        "text": "Expect a mild day with some cloud cover. A light jacket is recommended for the evening."
      },
      "children": []
    },
    "weather_details_table": {
      "type": "Table",
      "props": {
        "statePath": "/weatherData",
        "columns": [
          {
            "key": "metric",
            "label": "Metric"
          },
          {
            "key": "value",
            "label": "Value"
          }
        ],
        "domain": "weather",
        "preferredPresentation": "cards",
        "primaryColumn": "metric",
        "highlightColumns": [
          "value"
        ]
      },
      "children": []
    },
    "packing_essentials_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "packing_heading",
        "packing_table"
      ]
    },
    "packing_heading": {
      "type": "Text",
      "props": {
        "text": "Packing Essentials",
        "variant": "h3"
      },
      "children": []
    },
    "packing_table": {
      "type": "Table",
      "props": {
        "statePath": "/packingItems",
        "columns": [
          {
            "key": "item",
            "label": "Item"
          },
          {
            "key": "reason",
            "label": "Reason"
          }
        ],
        "domain": "generic",
        "preferredPresentation": "cards",
        "primaryColumn": "item",
        "highlightColumns": [
          "reason"
        ]
      },
      "children": []
    },
    "quick_actions_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "actions_heading",
        "actions_stack"
      ]
    },
    "actions_heading": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "wrap": "wrap"
      },
      "children": [
        "forecast_button",
        "map_button"
      ]
    },
    "forecast_button": {
      "type": "Button",
      "props": {
        "label": "View 5-Day Forecast"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.bbc.co.uk/weather/2643743"
          }
        }
      }
    },
    "map_button": {
      "type": "Button",
      "props": {
        "label": "Open Map"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.google.com/maps/place/London"
          }
        }
      }
    },
    "sources_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "sources_heading",
        "weather_source_button"
      ]
    },
    "sources_heading": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "weather_source_button": {
      "type": "Button",
      "props": {
        "label": "Weather data from BBC Weather"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.bbc.co.uk/weather/2643743"
          }
        }
      }
    }
  }
}
